"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1000-01-01:1":{"b": ["Ragusa (Dubrovnik) i južnodalmatinski gradovi prisegnuli su Orseolu", "6121e2e9"], "d": ["U Orseolovom dalmatinskom pohodu Ragusa, najjužniji od dalmatinskih gradova, s izaslanicima i nadbiskupom dočekala je duždevu vojsku na otočiću San Massimo i izrazila vjernost Veneciji.", "638f8cad"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1013-01-01:0":{"b": ["Mahmud je oduzeo Lahor Hindušahijima; Lahor je postao najomiljeniji grad Gaznevida", "37ab3445"], "d": ["Lahor, koji je od 991. bio u rukama Hindušahija, 1013–1014. prešao je u ruke Mahmuda Gaznevija; Mahmud je utvrdio lahorsku tvrđavu i uspostavio posadu od turskih i tadžičkih vojnika koje je doveo iz Horasana. Kada su Gaznevidi izgubili neovisnost (poslije 1157), Lahor je postao središte dijela koji je opstao na istoku.", "90b6f385"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1015-01-01:0":{"b": ["Kralj Robert II, nakon rata od trinaest godina, pripaja Burgundsko vojvodstvo francuskoj kruni", "257ea2c6"], "d": ["Nakon smrti vojvode Henrika 1002. izbio je rat za Burgundsko vojvodstvo; francuski kralj Robert II, uprkos otporu burgundskog grofa Otona Vilima, na kraju trinaestogodišnjeg rata 1015. pripojio je vojvodstvo kraljevstvu i dao ga sinu Henriku (kasnijem Henriku I).", "9b353b9c"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1018-01-01:0":{"b": ["Vasilije II ušao je u Ohrid: zapadnobugarska prijestolnica pala je u bizantske ruke", "05fe0972"], "d": ["Bugarska dinastija, koja se četiri godine nakon Samuilove smrti opirala, početkom 1018. predala se Vasiliju II na vratima Ohrida. Ohridska arhiepiskopija, međutim, opstala je pod bizantskom upravom kao središte slavenskog kršćanstva.", "b6ac5adb"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1018-01-01:1":{"b": ["Poljski kralj Boleslav Hrabri uz njemačku i pečenešku podršku zauzeo je Kijev", "3e44ca65"], "d": ["U augustu 1018. Boleslav je s njemačkim i pečeneškim snagama zauzeo Kijev; pobijedivši Jaroslava na rijeci Bug, na prijestolje je postavio svog zeta Svjatopolka. Jaroslav je Kijev mogao povratiti tek 1019.", "33889946"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1018-05-20:0":{"b": ["Mahmud je zagospodario gradom Mathurom (Muttra)", "78547f01"], "d": ["Tokom pohoda na Kannauj gaznevidska vojska zagospodarila je gradom Mathurom, koji se nalazi otprilike na pola puta između Delhija i Agre (409/1018).", "bb198817"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1018-12-20:0":{"b": ["Mahmud je osvojio Kannauj (Kanyakubju)", "258b5624"], "d": ["Mahmud je 13. džumadel-ula 409. (27. septembra 1018.) krenuo iz Gazne u dvanaesti indijski pohod; nakon tvrđave Sarsave, pokoravanja raje Barana i Mathure, glavni cilj Kannauj osvojen je 8. šabana 409. (20. decembra 1018.).", "5952deed"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1028-01-01:0":{"b": ["Knut Veliki proglašen je kraljem Norveške; Olaf Haraldsson je pobjegao", "89688331"], "d": ["Knut je 1028. s flotom od pedeset brodova došao u Norvešku i na Øretingu je aklamiran za norveškog kralja; kralj Olaf II Haraldsson pobjegao je najprije u Švedsku, a zatim u Rusiju (Gardariki).", "35460867"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1030-01-01:0":{"b": ["Osnovana je Aversanska grofovija: Rainulf Drengot postao je normanski grof", "ec99b57a"], "d": ["Kada je 1030. napuljski vojvoda Sergije naselio Rainulfa u tvrđavu Aversu, Normani su prvi put stekli trajnu bazu i počelo je organizirano osvajanje južne Italije.", "8d2a9071"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1033-01-01:0":{"b": ["Benu Ifren uzimaju grad Fes od Hamame b. Muiza.", "6cad34e9"], "d": ["Benu Ifren uzimaju grad Fes od Hamame b. Muiza.", "6cad34e9"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1038-01-01:0":{"b": ["Gvaimar je uzeo Capuu od ujaka i podvrgao i Amalfi, Sorrento i Gaetu", "3b8444df"], "d": ["Gvaimar uzima Capuu od svog ujaka Pandolfa IV; zatim podvrgava i Amalfi, Sorrento i Gaetu i dobija priznanje cara Konrada II.", "9e207542"]},
