"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1057-03-10:0":{"b": ["Ziridski emir Muiz napustio je Kajrevan i otišao u Mahdiju; Kajrevan je pao u ruke Hilalija", "becee655"], "d": ["Zbog opsade Benu Hilala, Muiz b. Badis 449. (1057) napustio je Kajrevan i otišao u Mahdiju, gdje je namjesnik bio njegov sin Temim; nebranjeni Kajrevan beduini su opljačkali i spalili.", "7b6732bb"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1061-01-01:0":{"b": ["Grof Roger zauzeo je Messinu (1061)", "28b31d9a"], "d": ["Roger se 1061. iskrcao u okolini Messine i relativno lahko zauzeo grad; tako je počelo normansko osvajanje Sicilije. TDV tu godinu navodi kao zauzimanje Messine.", "d06afdbf"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1067-01-01:0":{"b": ["Alp-Arslan osvojio je bizantski Kars; gruzijski kralj postao je vazal Seldžuka", "25994288"], "d": ["Alp-Arslan 1067. ponovo se pojavio na granicama Bizanta i Gruzije; osvojen je bizantski Kars i gruzijski kralj postao je vazal Seldžuka.", "5395feca"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1067-01-01:1":{"b": ["Alp-Arslan zauzeo je Kayseri", "c40df514"], "d": ["U doba seldžučkog sultana Alp-Arslana Turci su 1065. zauzeli Ani, a 1067. Kayseri; Bizant je izgubio vrata Kapadokije.", "fbeb3963"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1071-01-01:0":{"b": ["Katanija (Catania) pala je u normanske ruke (1071)", "21617f1b"], "d": ["Dok je trajala opsada Barija, Catania je 1071. zbog izdaje u gradu pala u normanske ruke; grad je zatim izgubljen i trajno zauzet oko deset godina kasnije.", "3d49a9a2"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1072-01-01:0":{"b": ["Mazara je pala u normanske ruke (1072)", "e7cb9667"], "d": ["Godine 1072., kada je zauzet Palermo, osvojena je i Mazara; u sljedećim godinama ondje je podignuta tvrđava i pružen otpor napadu iz sjeverne Afrike (1075).", "95450106"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1072-12-15:0":{"b": ["Nasr II je po Alp-Arslanovoj smrti zauzeo Termez, zatim krenuo na Balh i zauzeo i njega", "7747ccc9"], "d": ["Kada je Alp-Arslan umro u pohodu na Maveraunnehr, zapadnokarahanidski Šemsulmulk Nasr II zauzeo je Termez u mjesecu rebiu-l-ahiru 465. (decembar 1072), zatim krenuo na Balh i zauzeo i njega; seldžučko-karahanidska borba nastavila se u doba Melik-šaha.", "1ba5253a"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1073-01-01:0":{"b": ["Amalfi se protiv pritiska Salerna obraća Robertu Guiscardu; Normani zauzimaju grad i neovisnost...", "3d375631"], "d": ["Amalfi se protiv pritiska Salerna obraća Robertu Guiscardu; Normani zauzimaju grad i neovisnost prestaje.", "be93237a"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1075-08-16:0":{"b": ["Melik-šahov emir Savtegin zauzeo je Arran; gandžanski ogranak Šeddadida okončan je", "e031fc26"], "d": ["U doba šeddadida Fadla III jedan od emira sultana Melik-šaha, Savtegin, zauzeo je Arran (468/1075–76); oblast je došla pod seldžučku upravu i okončan je gandžanski ogranak Šeddadida.", "b39c17bd"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1076-01-01:0":{"b": ["Salerno je pao pod Roberta Guiscarda; okončana je Lombardska Salernska kneževina", "c678238f"], "d": ["Nakon dugog otpora Salerno se u decembru 1076. predao Robertu Guiscardu; knez Gisulf II povukao se u progonstvo, na papinski dvor. Guiscard je Salerno učinio glavnim gradom svog vojvodstva.", "705fecee"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1077-01-01:0":{"b": ["Roger je s flotom zauzeo Trapani", "2b0b3d98"], "d": ["Stvorivši flotu, Roger je 1077. pojačao ratne aktivnosti i zauzeo Trapani, a zatim Castronovo.", "6e482ca5"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1077-07-25:0":{"b": ["Jusuf b. Tašfin zauzeo je Tanger", "aa4376c4"], "d": ["Almoravidski emir Jusuf b. Tašfin zauzeo je Tanger, važan obalni grad Magribi-Aksa, 470. godine (1077–78).", "94bf21ec"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1081-01-01:0":{"b": ["Robert Guiscard iskrcao se kod Valone i zauzeo Krf", "d5e43c94"], "d": ["Guiscard je 1081. s flotom krenuo na Valonu (Avlonu), zauzeo Krf, a 1082. Drač; pohod na Konstantinopolj prekinut je jer je pozvan u Rim u pomoć Grguru VII.", "f805ca31"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1084-03-24:0":{"b": ["Rim se predaje Henriku IV; antipapa Klement III (Gvibert) postavlja se na prijestolje, Henrik dobija carsku krunu, Grgur bježi iz Rima", "311cfeb4"], "d": ["Rimljani su Henriku, koji se 1081. spustio u Italiju, predali grad; ravenski nadbiskup Gvibert 24. marta 1084. proglašen je papom pod imenom Klement III, a Henrika je protupapa okrunio za cara. Grgur VII, kojeg je napustilo trinaest kardinala, morao je pobjeći iz Rima; oslonio se na podršku Normana.", "996d4e46"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1084-05-10:0":{"b": ["Almoravidi su zagospodarili Ceutom (Sebtom)", "48f062fb"], "d": ["Jusuf b. Tašfin 477. godine (1084) stavio je Ceutu (Sebtu) pod svoju vlast; to su postala vrata za prelazak u Andaluziju.", "4ba802e3"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1085-01-01:0":{"b": ["Sulejman-šahov emir Buldadži osvojio je oblast Džejhan (Elbistan)", "406d5385"], "d": ["Oblast Džejhan (Elbistan), meta upada turkmenskih gazija, osvojio je 1085. Buldadži, jedan od emira anadolijskog seldžučkog sultana Sulejman-šaha.", "f1f8ec8c"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1086-01-01:0":{"b": ["Sirakuza (Syracuse) pala je pod Normane", "0d66d006"], "d": ["Nakon pada Agrigenta u julu 1086., u oktobru 1086. Sirakuza je pala u normanske ruke; Castrogiovanni će se predati 1087., a Noto 1091.", "b99596a6"]},
