"OLAYLAR_ORTACAG_ORTADOGU:0750-01-16:0":{"b": ["Počela bitka na Zabu; Abdullah b. Ali porazio Mervana II i rasuo umajadsku vojsku.", "d9b81d02"], "d": ["Počela bitka na Zabu; Abdullah b. Ali porazio Mervana II i rasuo umajadsku vojsku.", "d9b81d02"]},
"OLAYLAR_ORTACAG_ORTADOGU:0750-01-25:0":{"b": ["Veliki Zab: Mervan II pretrpio težak poraz od Abasida", "8d223056"], "d": ["Bitka koja je počela 2. džumadel-uhra 132 (16. januara 750) završila se ujutro u subotu 11. džumadel-uhra (25. januara) teškim Mervanovim porazom.", "cb560e7f"]},
"OLAYLAR_ORTACAG_ORTADOGU:0754-01-01:0":{"b": ["Mansur postao halifa (754-775); počelo razdoblje koje se smatra stvarnim utemeljenjem hilafeta.", "cf491add"], "d": ["Mansur postao halifa (754-775); počelo razdoblje koje se smatra stvarnim utemeljenjem hilafeta.", "cf491add"]},
"OLAYLAR_ORTACAG_ORTADOGU:0786-07-03:0":{"b": ["Harun er-Rašid postao halifa (170/786); počelo razdoblje koje se smatra vrhuncem abasidske moći.", "da851618"], "d": ["Harun er-Rašid postao halifa (170/786); počelo razdoblje koje se smatra vrhuncem abasidske moći.", "da851618"]},
