"OLAYLAR_ORTACAG_ORTADOGU:1312-08-30:0":{"b": ["Ebu l-Fida s titulom 'el-Melik es-Salih' postao melik Hame (25. rebiul-ahir 712).", "e03a1512"], "d": ["Ebu l-Fida s titulom 'el-Melik es-Salih' postao melik Hame (25. rebiul-ahir 712).", "e03a1512"]},
"OLAYLAR_ORTACAG_ORTADOGU:1320-02-28:0":{"b": ["Ebu l-Fida dobio titulu sultana (17. muharrem 720).", "8ae22f37"], "d": ["Ebu l-Fida dobio titulu sultana (17. muharrem 720).", "8ae22f37"]},
"OLAYLAR_ORTACAG_ORTADOGU:1331-01-01:0":{"b": ["Umro Ebu l-Fida (732/1331); hamski bejluk prešao njegovom sinu el-Efdalu Muhammedu.", "496b786e"], "d": ["Umro Ebu l-Fida (732/1331); hamski bejluk prešao njegovom sinu el-Efdalu Muhammedu.", "496b786e"]},
